-- Results + community database schema for Kookrabosss.
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, username text unique not null, role text not null default 'user' check (role in ('user','admin')), created_at timestamptz not null default now());
create table if not exists public.results (id bigint generated by default as identity primary key, market_name text not null, result_date date not null, result_value text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(market_name,result_date));
create table if not exists public.forum_posts (id bigint generated by default as identity primary key, user_id uuid not null references public.profiles(id) on delete cascade, title text not null check (char_length(title) between 3 and 120), body text not null check (char_length(body) between 3 and 5000), created_at timestamptz not null default now());
create table if not exists public.forum_comments (id bigint generated by default as identity primary key, post_id bigint not null references public.forum_posts(id) on delete cascade, user_id uuid not null references public.profiles(id) on delete cascade, body text not null check (char_length(body) between 1 and 2000), created_at timestamptz not null default now());
-- RLS policies are also applied to the connected Supabase project.
-- Admin authorization uses private.is_admin() so role checks are not client-controlled.
